-- 101: centroidi dei CAP italiani.
--
-- PERCHÉ
-- La distanza fra cliente e professionista (punti_distanza in
-- professionals_score, oggi solo una colonna di confronto) sta per entrare
-- nel punteggio vero. Le contiamo fra due punti fissi — il centro del CAP di
-- chi cerca e il centro del CAP di chi lavora — non fra indirizzi esatti:
-- l'indirizzo del cliente non arriva mai al matching (consegna progressiva,
-- docs/DATA_COMPLIANCE.md §4) e quello del professionista non è più preciso
-- di quanto serva. Questa tabella è il centro di ogni CAP, la geografia
-- pubblica che serve a calcolarla in SQL invece che portarsi dietro un
-- servizio di geocoding esterno per ogni richiesta.
--
-- FONTE E DATA
-- GeoNames, https://download.geonames.org/export/zip/IT.zip (CC BY 4.0,
-- vedi readme.txt nell'archivio). Scaricato il 2026-09-28. 18414 righe di
-- partenza (una per località, un CAP può averne più di una), collassate a
-- una riga per CAP mediando lat/lng dove serve — 4735 CAP distinti nel
-- risultato.
--
-- CONFRONTO CON comuni.cap
-- comuni.cap despiegato dà 4678 CAP distinti (086); GeoNames ne copre di più
-- perché include suddivisioni che il nostro elenco comuni non porta. 120 CAP
-- di comuni.cap non hanno però un centroide GeoNames — ma non sono un solo
-- difetto, sono tre cose diverse, verificate contro la ricerca CAP di Poste:
--
-- 1) CAP GENERICI (caselle postali e grandi utenti), nessun indirizzo
--    civico: qui GeoNames non manca niente, perché non c'è nessuna via a cui
--    appaiare una coordinata. Milano 20130, 20140, 20150, 20160; Roma 00130,
--    00140, 00150, 00160, 00170, 00180, 00190; Napoli 80130, 80140; Bologna
--    40130, 40140; Palermo 90130, 90150; e con lo stesso schema (tondo,
--    comune già coperto da un altro CAP) Venezia 30130, 30140, 30150, 30160
--    e Ancona 60130. Milano è quindi coperta per intero ai fini del pilota:
--    nessun CAP mancante lì è un indirizzo reale senza centroide.
-- 2) CAP CIVICI REALI CHE GEONAMES NON COPRE. Verificati come esistenti:
--    Cagliari 09050–09069, Ravenna 48121–48125, e il resto di questo elenco:
--    00129, 04031, 07051, 07052, 09089, 09132, 09133, 10079, 13029, 15047,
--    15122, 18028, 28921, 28923, 28924, 28925, 29031, 30134, 30136, 30137,
--    30138, 30139, 30143, 30144, 30145, 30146, 30147, 30148, 30149, 30151,
--    30152, 30153, 30154, 30155, 30156, 30157, 30158, 30159, 30161, 30162,
--    30163, 30164, 30165, 30166, 30167, 30168, 30169, 30176, 33012, 33014,
--    36044, 36048, 41123, 43046, 47521, 47522, 52019, 61036, 62031, 71051,
--    80072, 80081, 82014, 87059, 90051, 92031. QUI SÌ CHE C'È UNA CONSEGUENZA:
--    il giorno che Bob apre una di queste città, ogni professionista lì
--    dentro collassa sullo stesso centroide di comune e punti_distanza
--    smette di distinguere — esattamente il difetto che questa migrazione e
--    la 102 esistono per chiudere a Milano. Servono centroidi veri per questi
--    ~110 CAP prima che una seconda città vada in produzione.
-- 3) ESITO INCERTO. Mestre 30127, 30128, 30129 e La Spezia 19127, 19128,
--    19129, 19130 non hanno dato risposta nella ricerca di Poste, né come
--    esistenti né come aboliti: forse rinumerati, forse ritirati. Non
--    verificati, da non fidarsi finché qualcuno non lo controlla meglio.
--
-- Nessuna riga qui per nessuno dei 120: chi li interroga ricade sul
-- centroide del comune (fallback già previsto in professionals_score).
--
-- CONFORMITÀ
-- Nessun dato personale: geografia pubblica, stessa postura di comuni (086).
-- Lettura per tutti, nessuna policy di scrittura — la popola solo questa
-- migrazione, non un form né un ruolo applicativo.
--
-- Idempotente: create table if not exists, upsert sulla chiave primaria.
-- Il seed è spezzato in blocchi da 500 righe, come la 086 per lo stesso
-- motivo: una insert sola da 4735 non passa da tutte le strade con cui
-- questo file può essere applicato.

create table if not exists public.cap_centroids (
  cap text primary key,
  lat double precision not null,
  lng double precision not null,
  source text,
  updated_at timestamptz not null default now()
);

alter table public.cap_centroids enable row level security;

-- Geografia pubblica: nessun dato personale, lettura per tutti, nessuna
-- scrittura applicativa (la tabella la scrive solo questa migrazione).
drop policy if exists "Anyone reads cap_centroids" on public.cap_centroids;
create policy "Anyone reads cap_centroids" on public.cap_centroids
  for select using (true);

comment on table public.cap_centroids is
  'Centro di ogni CAP italiano. Geografia pubblica (GeoNames, CC BY 4.0, scaricato 2026-09-28, vedi NOTE_E_DECISIONI). Nessuna scrittura applicativa: la popola solo questa migrazione.';
comment on column public.cap_centroids.cap is
  'CAP a cinque cifre, zeri davanti compresi.';
comment on column public.cap_centroids.source is
  'GeoNames (CC BY 4.0), https://download.geonames.org/export/zip/IT.zip, scaricato 2026-09-28.';

